                local quality = nil
                local percent = nil
                local attrs = item:GetAttributes()

                local qualityKeys = {
                    "ReforgeQuality",
                    "QualityName",
                    "Quality",
                    "ReforgeGrade",
                    "QualityGrade",
                }

                local percentKeys = {
                    "ReforgePercent",
                    "ReforgePercentage",
                    "QualityPercent",
                    "QualityPercentage",
                    "ReforgeBonusPercent",
                    "QualityBonusPercent",
                }

                for _, key in ipairs(qualityKeys) do
                    local value = attrs[key]
                    if value ~= nil then
                        quality = canonicalQuality(value)
